from __future__ import annotations

from pathlib import Path
import shutil


PROJECT_ROOT = Path(__file__).resolve().parents[2]
TARGET = (
    PROJECT_ROOT
    / "src"
    / "widget"
    / "delta"
    / "delta_logo_manager.py"
)

CORRECTED_CONTENT = 'from __future__ import annotations\n\nimport json\nimport re\nimport unicodedata\nfrom dataclasses import dataclass\nfrom difflib import SequenceMatcher\nfrom pathlib import Path\nfrom typing import Iterable\n\nfrom PySide6.QtGui import QPixmap\n\n\n@dataclass(slots=True)\nclass LogoMatch:\n    manufacturer: str\n    path: Path | None\n    matched_text: str = ""\n\n\nclass DeltaLogoManager:\n    """\n    Localiza logos usando múltiplos textos do LMU.\n\n    Compatível com:\n    - mVehicleName\n    - mVehFilename\n    - mPitGroup\n    - mVehicleModel\n    """\n\n    DEFAULT_ALIASES: dict[str, list[str]] = {\n        "alpine": ["alpine", "a424"],\n        "aston_martin": [\n            "aston martin",\n            "astonmartin",\n            "amr",\n            "vantage",\n            "valkyrie",\n        ],\n        "bmw": ["bmw", "m hybrid", "m4 gt3", "m8 gte"],\n        "cadillac": ["cadillac", "v-series", "v series"],\n        "chevrolet": ["chevrolet", "corvette", "z06 gt3"],\n        "duqueine": ["duqueine", "d08", "d09"],\n        "ferrari": ["ferrari", "499p", "296 gt3", "488 gte"],\n        "ford": ["ford", "mustang gt3"],\n        "genesis": ["genesis", "gmr-001", "gmr 001"],\n        "ginetta": ["ginetta"],\n        "glickenhaus": ["glickenhaus", "scg", "007 lmh", "007lmh"],\n        "honda": ["honda", "acura", "nsx"],\n        "isotta_fraschini": [\n            "isotta fraschini",\n            "isotta",\n            "tipo 6",\n            "tipo6",\n        ],\n        "lamborghini": ["lamborghini", "sc63", "huracan"],\n        "lexus": ["lexus", "rc f gt3", "rcf gt3"],\n        "ligier": ["ligier", "js p", "jsp"],\n        "mclaren": ["mclaren", "720s"],\n        "mercedes": [\n            "mercedes",\n            "mercedes benz",\n            "mercedes-amg",\n            "amg gt3",\n        ],\n        "oreca": ["oreca", "07 gibson", "oreca 07"],\n        "peugeot": ["peugeot", "9x8"],\n        "porsche": [\n            "porsche",\n            "porshce",\n            "963",\n            "911 gt3",\n            "911 rsr",\n        ],\n        "toyota": ["toyota", "gr010"],\n        "vanwall": ["vanwall", "vandervell"],\n        "dallara": ["dallara"],\n    }\n\n    FILE_ALIASES: dict[str, list[str]] = {\n        "aston_martin": ["aston martin", "astonmartin", "amr"],\n        "chevrolet": ["chevrolet", "corvette"],\n        "isotta_fraschini": [\n            "isotta fraschini",\n            "isotta_fraschini",\n            "isotta",\n        ],\n        "mclaren": ["mclaren", "mc laren"],\n        "mercedes": ["mercedes", "mercedes benz", "mercedes_benz"],\n        "porsche": ["porsche", "porshce"],\n    }\n\n    def __init__(\n        self,\n        project_root: Path,\n        configured_directory: str | None = None,\n    ) -> None:\n        self.project_root = Path(project_root)\n        self.logo_directory = self._resolve_directory(configured_directory)\n        self.aliases = self._load_aliases()\n        self._path_index = self._index_files()\n        self._pixmap_cache: dict[Path, QPixmap] = {}\n        self._directory_stamp = self._directory_signature()\n\n    def set_directory(self, configured_directory: str | None) -> None:\n        resolved = self._resolve_directory(configured_directory)\n\n        if resolved != self.logo_directory:\n            self.logo_directory = resolved\n\n        self.refresh()\n\n    def refresh(self) -> None:\n        self.aliases = self._load_aliases()\n        self._path_index = self._index_files()\n        self._pixmap_cache.clear()\n        self._directory_stamp = self._directory_signature()\n\n    def match(self, *vehicle_texts: str) -> LogoMatch:\n        """\n        Aceita um ou vários textos.\n\n        Exemplo:\n            match(vehicle_name, vehicle_filename, pit_group, player_model)\n        """\n        self._refresh_if_changed()\n\n        normalized_values = [\n            self._normalize(value)\n            for value in vehicle_texts\n            if str(value or "").strip()\n        ]\n        combined = " ".join(normalized_values).strip()\n\n        if not combined:\n            return LogoMatch(\n                manufacturer="Car",\n                path=self._path_for_manufacturer("default"),\n            )\n\n        for manufacturer, aliases in self.aliases.items():\n            for alias in aliases:\n                normalized_alias = self._normalize(alias)\n\n                if normalized_alias and normalized_alias in combined:\n                    path = self._path_for_manufacturer(manufacturer)\n\n                    if path is None:\n                        self.refresh()\n                        path = self._path_for_manufacturer(manufacturer)\n\n                    return LogoMatch(\n                        manufacturer=self._display_name(manufacturer),\n                        path=path,\n                        matched_text=alias,\n                    )\n\n        direct = self._direct_file_match(normalized_values)\n\n        if direct is not None:\n            manufacturer, path = direct\n            return LogoMatch(\n                manufacturer=self._display_name(manufacturer),\n                path=path,\n                matched_text=manufacturer,\n            )\n\n        return LogoMatch(\n            manufacturer="Car",\n            path=self._path_for_manufacturer("default"),\n            matched_text=combined,\n        )\n\n    def pixmap(self, path: Path | None) -> QPixmap | None:\n        if path is None or not path.exists():\n            return None\n\n        cached = self._pixmap_cache.get(path)\n\n        if cached is not None:\n            return cached\n\n        pixmap = QPixmap(str(path))\n\n        if pixmap.isNull():\n            return None\n\n        self._pixmap_cache[path] = pixmap\n        return pixmap\n\n    def diagnostics(self) -> dict[str, object]:\n        return {\n            "project_root": str(self.project_root),\n            "logo_directory": str(self.logo_directory),\n            "logo_directory_exists": self.logo_directory.exists(),\n            "indexed_keys": sorted(self._path_index.keys()),\n            "indexed_files": sorted(\n                str(path.name)\n                for path in set(self._path_index.values())\n            ),\n        }\n\n    def _resolve_directory(self, configured_directory: str | None) -> Path:\n        candidates: list[Path] = []\n\n        if configured_directory:\n            configured = Path(str(configured_directory).strip())\n            candidates.append(\n                configured\n                if configured.is_absolute()\n                else self.project_root / configured\n            )\n\n        candidates.extend(\n            [\n                self.project_root / "images" / "logos",\n                self.project_root / "images" / "logo",\n                self.project_root / "src" / "images" / "logos",\n                self.project_root / "images",\n            ]\n        )\n\n        for candidate in candidates:\n            if candidate.exists() and candidate.is_dir():\n                return candidate.resolve()\n\n        fallback = self.project_root / "images" / "logos"\n        fallback.mkdir(parents=True, exist_ok=True)\n        return fallback.resolve()\n\n    def _load_aliases(self) -> dict[str, list[str]]:\n        aliases = {\n            key: list(values)\n            for key, values in self.DEFAULT_ALIASES.items()\n        }\n        aliases_file = self.logo_directory / "manufacturer_aliases.json"\n\n        if aliases_file.exists():\n            try:\n                custom = json.loads(\n                    aliases_file.read_text(encoding="utf-8")\n                )\n\n                for key, values in custom.items():\n                    if not isinstance(values, list):\n                        continue\n\n                    canonical = self._canonical_key(str(key))\n                    current = aliases.setdefault(canonical, [])\n\n                    for value in values:\n                        text = str(value)\n\n                        if text not in current:\n                            current.append(text)\n\n            except (OSError, json.JSONDecodeError):\n                pass\n\n        return aliases\n\n    def _index_files(self) -> dict[str, Path]:\n        result: dict[str, Path] = {}\n        allowed = {".png", ".jpg", ".jpeg", ".webp"}\n\n        if not self.logo_directory.exists():\n            return result\n\n        for path in self.logo_directory.iterdir():\n            if not path.is_file() or path.suffix.lower() not in allowed:\n                continue\n\n            normalized = self._normalize(path.stem)\n            canonical = self._canonical_key(path.stem)\n            compact = self._compact(normalized)\n\n            for key in {normalized, canonical, compact}:\n                if key:\n                    result.setdefault(key, path)\n\n        return result\n\n    def _path_for_manufacturer(self, manufacturer: str) -> Path | None:\n        candidates = [\n            manufacturer,\n            manufacturer.replace("_", " "),\n            manufacturer.replace("_", ""),\n        ]\n        candidates.extend(self.FILE_ALIASES.get(manufacturer, []))\n\n        for candidate in candidates:\n            normalized = self._normalize(candidate)\n            keys = {\n                normalized,\n                self._canonical_key(candidate),\n                self._compact(normalized),\n            }\n\n            for key in keys:\n                path = self._path_index.get(key)\n\n                if path is not None:\n                    return path\n\n        target = self._compact(\n            self._normalize(manufacturer.replace("_", " "))\n        )\n        best_ratio = 0.0\n        best_path: Path | None = None\n\n        for key, path in self._path_index.items():\n            ratio = SequenceMatcher(\n                None,\n                target,\n                self._compact(key),\n            ).ratio()\n\n            if ratio > best_ratio:\n                best_ratio = ratio\n                best_path = path\n\n        return best_path if best_ratio >= 0.74 else None\n\n    def _direct_file_match(\n        self,\n        normalized_values: Iterable[str],\n    ) -> tuple[str, Path] | None:\n        combined = " ".join(normalized_values)\n        combined_compact = self._compact(combined)\n\n        for key, path in self._path_index.items():\n            compact_key = self._compact(key)\n\n            if compact_key and compact_key in combined_compact:\n                return key, path\n\n        return None\n\n    def _refresh_if_changed(self) -> None:\n        current = self._directory_signature()\n\n        if current != self._directory_stamp:\n            self.refresh()\n\n    def _directory_signature(self) -> tuple[tuple[str, int, int], ...]:\n        if not self.logo_directory.exists():\n            return ()\n\n        signature: list[tuple[str, int, int]] = []\n\n        try:\n            for path in self.logo_directory.iterdir():\n                if not path.is_file():\n                    continue\n\n                stat = path.stat()\n                signature.append(\n                    (\n                        path.name.lower(),\n                        int(stat.st_mtime_ns),\n                        int(stat.st_size),\n                    )\n                )\n        except OSError:\n            return ()\n\n        return tuple(sorted(signature))\n\n    @classmethod\n    def _canonical_key(cls, value: str) -> str:\n        return cls._normalize(value).replace(" ", "_")\n\n    @staticmethod\n    def _compact(value: str) -> str:\n        return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())\n\n    @staticmethod\n    def _normalize(value: str) -> str:\n        normalized = unicodedata.normalize(\n            "NFKD",\n            str(value or ""),\n        )\n        normalized = "".join(\n            char\n            for char in normalized\n            if not unicodedata.combining(char)\n        )\n        normalized = normalized.lower().replace("_", " ")\n        normalized = re.sub(r"[^a-z0-9]+", " ", normalized)\n        return re.sub(r"\\s+", " ", normalized).strip()\n\n    @staticmethod\n    def _display_name(value: str) -> str:\n        return value.replace("_", " ").title()\n'


def main() -> None:
    TARGET.parent.mkdir(parents=True, exist_ok=True)

    if TARGET.exists():
        backup = TARGET.with_suffix(".py.bak")
        shutil.copy2(TARGET, backup)
        print(f"Backup criado: {backup}")

    TARGET.write_text(
        CORRECTED_CONTENT,
        encoding="utf-8",
    )

    print("OK - delta_logo_manager.py corrigido.")
    print()
    print("Assinatura instalada:")
    print("def match(self, *vehicle_texts: str) -> LogoMatch")
    print()
    print("Agora feche o overlay e execute:")
    print(r"python .\src\tools\run_sector_flow_lmu.py")


if __name__ == "__main__":
    main()
